import fs from "fs"
import path from "path"

const base = "src/content"

function writeLesson(moduleId, index, slug, exercises) {
  const dir = path.join(base, `${moduleId}/exercises`)
  fs.mkdirSync(dir, { recursive: true })
  const lessonId = moduleId + "-" + String(index + 1).padStart(2, "0") + "-" + slug
  exercises.forEach((ex, i) => {
    const file = slug + "-" + String(i + 1).padStart(2, "0") + ".json"
    fs.writeFileSync(path.join(dir, file), JSON.stringify({
      id: lessonId + "-" + String(i + 1).padStart(2, "0"),
      title: ex.title,
      starterCode: ex.starterCode,
      solution: ex.solution,
      tests: ex.tests,
      hints: ex.hints,
    }, null, 2))
  })
  console.log(moduleId + " " + slug + ": " + exercises.length + " exercises")
}

