// MODULE 04: CONTROL FLOW
// ═══════════════════════════════════════════════════════════

// 04-01: if-else-switch (50 exercises)
writeLesson("04-control-flow", 0, "if-else-switch", [
  { id: "04-01-01", title: "Age based ticket price decide karo", starterCode: '// function ticketPrice(age) mein age do\n// < 5: "Free", 5-12: 100, 13-59: 250, 60+: 150\n// "Free", 100, 250, ya 150 return karo\n', solution: 'function ticketPrice(age) {\n  if (age < 5) return "Free"\n  else if (age <= 12) return 100\n  else if (age <= 59) return 250\n  else return 150\n}', tests: [{ input: [3], expected: "Free" }, { input: [10], expected: 100 }, { input: [30], expected: 250 }, { input: [65], expected: 150 }], hints: ["if-else if chain se age ranges check karo", "Har condition ka alag return value hai"] },
  { id: "04-01-02", title: "Positive, negative ya zero check", starterCode: '// function checkNumber(num) mein number do\n// positive, negative, ya zero return karo\n', solution: 'function checkNumber(num) {\n  if (num > 0) return "positive"\n  else if (num < 0) return "negative"\n  else return "zero"\n}', tests: [{ input: [5], expected: "positive" }, { input: [-3], expected: "negative" }, { input: [0], expected: "zero" }], hints: ["num > 0 se positive check hota hai", "num < 0 se negative check hota hai"] },
  { id: "04-01-03", title: "Even ya odd number batao", starterCode: '// function evenOdd(num) mein number do\n// "even" ya "odd" return karo\n', solution: 'function evenOdd(num) {\n  if (num % 2 === 0) return "even"\n  else return "odd"\n}', tests: [{ input: [4], expected: "even" }, { input: [7], expected: "odd" }, { input: [0], expected: "even" }, { input: [-2], expected: "even" }], hints: ["% (modulo) operator se remainder milta hai", "0 remainder means even hai"] },
  { id: "04-01-04", title: "Grade system based on marks", starterCode: '// function getGrade(marks) mein marks do (0-100)\n// >=90: "A+", >=80: "A", >=70: "B", >=60: "C", >=50: "D", <50: "F"\n', solution: 'function getGrade(marks) {\n  if (marks >= 90) return "A+"\n  else if (marks >= 80) return "A"\n  else if (marks >= 70) return "B"\n  else if (marks >= 60) return "C"\n  else if (marks >= 50) return "D"\n  else return "F"\n}', tests: [{ input: [95], expected: "A+" }, { input: [82], expected: "A" }, { input: [71], expected: "B" }, { input: [45], expected: "F" }], hints: ["Sabse pehle highest range check karo", "Marks >= 90 se start karo chain"] },
  { id: "04-01-05", title: "Traffic light signal behavior", starterCode: '// function trafficLight(color) mein color string do\n// "red": "Stop", "yellow": "Wait", "green": "Go"\n// Invalid color ke liye "Invalid color" return karo\n', solution: 'function trafficLight(color) {\n  if (color === "red") return "Stop"\n  else if (color === "yellow") return "Wait"\n  else if (color === "green") return "Go"\n  else return "Invalid color"\n}', tests: [{ input: ["red"], expected: "Stop" }, { input: ["yellow"], expected: "Wait" }, { input: ["green"], expected: "Go" }, { input: ["blue"], expected: "Invalid color" }], hints: ["=== se exact string comparison karo", "Default case mein error message do"] },
  { id: "04-01-06", title: "Nested if se voting eligibility check", starterCode: '// function canVote(age, citizen) mein age aur boolean citizen do\n// citizen true aur age >= 18: "Eligible to vote"\n// citizen false: "Not a citizen"\n// age < 18: "Too young"\n', solution: 'function canVote(age, citizen) {\n  if (citizen) {\n    if (age >= 18) return "Eligible to vote"\n    else return "Too young"\n  } else {\n    return "Not a citizen"\n  }\n}', tests: [{ input: [25, true], expected: "Eligible to vote" }, { input: [15, true], expected: "Too young" }, { input: [30, false], expected: "Not a citizen" }], hints: ["Pehle citizenship check karo", "Phir nested mein age check karo"] },
  { id: "04-01-07", title: "Switch se day of week name batao", starterCode: '// function dayName(day) mein number 0-6 do\n// 0: "Sunday", 1: "Monday", ..., 6: "Saturday"\n// Invalid ke liye "Invalid day"\n', solution: 'function dayName(day) {\n  switch (day) {\n    case 0: return "Sunday"\n    case 1: return "Monday"\n    case 2: return "Tuesday"\n    case 3: return "Wednesday"\n    case 4: return "Thursday"\n    case 5: return "Friday"\n    case 6: return "Saturday"\n    default: return "Invalid day"\n  }\n}', tests: [{ input: [0], expected: "Sunday" }, { input: [3], expected: "Wednesday" }, { input: [6], expected: "Saturday" }, { input: [7], expected: "Invalid day" }], hints: ["switch-case mein har day ke liye case likho", "default se invalid handle karo"] },
  { id: "04-01-08", title: "Switch with fall-through for months", starterCode: '// function getSeason(month) mein number 1-12 do\n// 12,1,2: "Winter", 3,4,5: "Spring", 6,7,8: "Summer", 9,10,11: "Autumn"\n', solution: 'function getSeason(month) {\n  switch (month) {\n    case 12: case 1: case 2: return "Winter"\n    case 3: case 4: case 5: return "Spring"\n    case 6: case 7: case 8: return "Summer"\n    case 9: case 10: case 11: return "Autumn"\n    default: return "Invalid month"\n  }\n}', tests: [{ input: [1], expected: "Winter" }, { input: [5], expected: "Spring" }, { input: [8], expected: "Summer" }, { input: [10], expected: "Autumn" }], hints: ["Fall-through se multiple cases ek saath handle hote hain", "Break ki zaroorat nahi kyunki return hai"] },
  { id: "04-01-09", title: "Calculator operations using switch", starterCode: '// function calculate(a, op, b) mein do numbers aur operator do\n// "+", "-", "*", "/" ke liye result return karo\n// Division by zero: "Cannot divide by zero"\n// Invalid operator: "Unknown operator"\n', solution: 'function calculate(a, op, b) {\n  switch (op) {\n    case "+": return a + b\n    case "-": return a - b\n    case "*": return a * b\n    case "/": return b !== 0 ? a / b : "Cannot divide by zero"\n    default: return "Unknown operator"\n  }\n}', tests: [{ input: [10, "+", 5], expected: 15 }, { input: [10, "-", 5], expected: 5 }, { input: [10, "*", 5], expected: 50 }, { input: [10, "/", 0], expected: "Cannot divide by zero" }], hints: ["Switch mein har operator ka case banao", "Division by zero pe special case handle karo"] },
  { id: "04-01-10", title: "Guard clause se early return karo", starterCode: '// function divide(a, b) mein do numbers do\n// Agar b === 0 hai to "Cannot divide by zero" return karo (pehle hi)\n// Warna a/b return karo\n', solution: 'function divide(a, b) {\n  if (b === 0) return "Cannot divide by zero"\n  return a / b\n}', tests: [{ input: [10, 2], expected: 5 }, { input: [7, 0], expected: "Cannot divide by zero" }, { input: [0, 5], expected: 0 }], hints: ["Guard clause function ke start mein hota hai", "Early return se nesting kam hoti hai"] },
  { id: "04-01-11", title: "Nested if se BMI category batao", starterCode: '// function bmiCategory(weight, height) mein kg aur meters do\n// BMI = weight / (height * height)\n// < 18.5: "Underweight", 18.5-24.9: "Normal", 25-29.9: "Overweight", >=30: "Obese"\n', solution: 'function bmiCategory(weight, height) {\n  const bmi = weight / (height * height)\n  if (bmi < 18.5) return "Underweight"\n  else if (bmi <= 24.9) return "Normal"\n  else if (bmi <= 29.9) return "Overweight"\n  else return "Obese"\n}', tests: [{ input: [50, 1.7], expected: "Normal" }, { input: [100, 1.7], expected: "Overweight" }, { input: [40, 1.7], expected: "Underweight" }, { input: [120, 1.7], expected: "Obese" }], hints: ["Pehle BMI calculate karo formula se", "Phir ranges ke hisaab se category return karo"] },
  { id: "04-01-12", title: "Nested if se discount calculate karo", starterCode: '// function calculateDiscount(amount, isMember, isNew)\n// Member aur new: 30% off\n// Sirf member: 20% off\n// Sirf new: 10% off\n// Dono nahi: 0% off\n', solution: 'function calculateDiscount(amount, isMember, isNew) {\n  if (isMember && isNew) return amount * 0.7\n  else if (isMember) return amount * 0.8\n  else if (isNew) return amount * 0.9\n  else return amount\n}', tests: [{ input: [1000, true, true], expected: 700 }, { input: [1000, true, false], expected: 800 }, { input: [1000, false, true], expected: 900 }, { input: [1000, false, false], expected: 1000 }], hints: ["&& se dono conditions check hoti hain", "Pehle combined condition check karo phir alag alag"] },
  { id: "04-01-13", title: "Character type detect karo", starterCode: '// function charType(char) mein single character do\n// Digit: "digit", Letter: "letter", Special: "special"\n', solution: 'function charType(char) {\n  if (char >= "0" && char <= "9") return "digit"\n  else if ((char >= "a" && char <= "z") || (char >= "A" && char <= "Z")) return "letter"\n  else return "special"\n}', tests: [{ input: ["5"], expected: "digit" }, { input: ["a"], expected: "letter" }, { input: ["Z"], expected: "letter" }, { input: ["@"], expected: "special" }], hints: ["Char comparison se range check hota hai", "'a' <= char && char <= 'z' se letter detect hota hai"] },
  { id: "04-01-14", title: "Rock paper scissors result", starterCode: '// function rps(player, computer) mein dono strings do ("rock","paper","scissors")\n// "win", "lose", ya "draw" return karo\n', solution: 'function rps(player, computer) {\n  if (player === computer) return "draw"\n  if (\n    (player === "rock" && computer === "scissors") ||\n    (player === "paper" && computer === "rock") ||\n    (player === "scissors" && computer === "paper")\n  ) return "win"\n  return "lose"\n}', tests: [{ input: ["rock", "rock"], expected: "draw" }, { input: ["rock", "scissors"], expected: "win" }, { input: ["rock", "paper"], expected: "lose" }, { input: ["paper", "rock"], expected: "win" }], hints: ["Pehle draw check karo same values se", "Win conditions: rock>scissors, paper>rock, scissors>paper"] },
  { id: "04-01-15", title: "Form validation multiple conditions", starterCode: '// function validateForm(name, email, age) mein three values do\n// Name empty: "Name is required"\n// Email mein @ nahi: "Invalid email"\n// Age < 18: "Must be 18+"\n// Sab valid: "Form is valid"\n', solution: 'function validateForm(name, email, age) {\n  if (!name) return "Name is required"\n  if (!email.includes("@")) return "Invalid email"\n  if (age < 18) return "Must be 18+"\n  return "Form is valid"\n}', tests: [{ input: ["", "test@test.com", 25], expected: "Name is required" }, { input: ["Hariom", "invalid", 25], expected: "Invalid email" }, { input: ["Hariom", "test@test.com", 15], expected: "Must be 18+" }, { input: ["Hariom", "test@test.com", 25], expected: "Form is valid" }], hints: ["Har validation ke liye alag if check karo", "Guard clause pattern use karo pehle pehle"] },
  { id: "04-01-16", title: "Nested if se permission check", starterCode: '// function checkAccess(role, isOnline, hasSubscription)\n// Admin: "Full access"\n// Online + Subscriber: "Premium access"\n// Online: "Basic access"\n// Offline: "No access"\n', solution: 'function checkAccess(role, isOnline, hasSubscription) {\n  if (role === "admin") return "Full access"\n  if (!isOnline) return "No access"\n  if (hasSubscription) return "Premium access"\n  return "Basic access"\n}', tests: [{ input: ["admin", false, false], expected: "Full access" }, { input: ["user", true, true], expected: "Premium access" }, { input: ["user", true, false], expected: "Basic access" }, { input: ["user", false, true], expected: "No access" }], hints: ["Admin ko hamesha full access do", "Offline hai to kuch nahi milega"] },
  { id: "04-01-17", title: "Temperature description with nested if", starterCode: '// function tempDescription(tempC) mein Celsius do\n// >= 45: "Extreme heat", >=35: "Very hot", >=25: "Warm", >=15: "Pleasant", >=5: "Cool", <5: "Cold"\n', solution: 'function tempDescription(tempC) {\n  if (tempC >= 45) return "Extreme heat"\n  else if (tempC >= 35) return "Very hot"\n  else if (tempC >= 25) return "Warm"\n  else if (tempC >= 15) return "Pleasant"\n  else if (tempC >= 5) return "Cool"\n  else return "Cold"\n}', tests: [{ input: [48], expected: "Extreme heat" }, { input: [38], expected: "Very hot" }, { input: [28], expected: "Warm" }, { input: [18], expected: "Pleasant" }, { input: [8], expected: "Cool" }, { input: [0], expected: "Cold" }], hints: ["Sabse pehle highest range check karo", "Order matters — descending mein check karo"] },
  { id: "04-01-18", title: "Switch se color code return karo", starterCode: '// function colorCode(color) mein color name do\n// "red": "#FF0000", "green": "#00FF00", "blue": "#0000FF"\n// Unknown: "#000000"\n', solution: 'function colorCode(color) {\n  switch (color.toLowerCase()) {\n    case "red": return "#FF0000"\n    case "green": return "#00FF00"\n    case "blue": return "#0000FF"\n    default: return "#000000"\n  }\n}', tests: [{ input: ["red"], expected: "#FF0000" }, { input: ["Green"], expected: "#00FF00" }, { input: ["BLUE"], expected: "#0000FF" }, { input: ["yellow"], expected: "#000000" }], hints: ["toLowerCase() se case-insensitive comparison hota hai", "Default case mein black return karo"] },
  { id: "04-01-19", title: "Nested if se login status", starterCode: '// function loginStatus(username, password, isBlocked)\n// Blocked: "Account blocked"\n// Wrong credentials: "Invalid credentials"\n// Sab sahi: "Welcome back"\n', solution: 'function loginStatus(username, password, isBlocked) {\n  if (isBlocked) return "Account blocked"\n  if (username !== "admin" || password !== "1234") return "Invalid credentials"\n  return "Welcome back"\n}', tests: [{ input: ["admin", "1234", true], expected: "Account blocked" }, { input: ["wrong", "1234", false], expected: "Invalid credentials" }, { input: ["admin", "wrong", false], expected: "Invalid credentials" }, { input: ["admin", "1234", false], expected: "Welcome back" }], hints: ["Pehle blocked status check karo", "Phir credentials verify karo"] },
  { id: "04-01-20", title: "Age group categorize karo", starterCode: '// function ageGroup(age) mein number do\n// 0-1: "Infant", 2-5: "Toddler", 6-12: "Child", 13-17: "Teen", 18-64: "Adult", 65+: "Senior"\n', solution: 'function ageGroup(age) {\n  if (age <= 1) return "Infant"\n  else if (age <= 5) return "Toddler"\n  else if (age <= 12) return "Child"\n  else if (age <= 17) return "Teen"\n  else if (age <= 64) return "Adult"\n  else return "Senior"\n}', tests: [{ input: [0], expected: "Infant" }, { input: [3], expected: "Toddler" }, { input: [10], expected: "Child" }, { input: [15], expected: "Teen" }, { input: [30], expected: "Adult" }, { input: [70], expected: "Senior" }], hints: ["Age <= se check karo ranges", "Order ascending mein rakho"] },
  { id: "04-01-21", title: "Number type check karo", starterCode: '// function numberType(num) mein value do\n// Integer: "integer", Float: "float", NaN: "not a number"\n', solution: 'function numberType(num) {\n  if (Number.isNaN(num)) return "not a number"\n  if (Number.isInteger(num)) return "integer"\n  return "float"\n}', tests: [{ input: [42], expected: "integer" }, { input: [3.14], expected: "float" }, { input: [NaN], expected: "not a number" }, { input: [42.0], expected: "integer" }], hints: ["Number.isNaN() se NaN check hota hai", "Number.isInteger() se integer check hota hai"] },
  { id: "04-01-22", title: "Nested if se password strength", starterCode: '// function passwordStrength(password) mein string do\n// <6 chars: "Weak", 6-10: "Medium", >10 with special char: "Strong"\n// >10 bina special char: "Medium"\n', solution: 'function passwordStrength(password) {\n  if (password.length < 6) return "Weak"\n  if (password.length > 10) {\n    if (/[^a-zA-Z0-9]/.test(password)) return "Strong"\n    else return "Medium"\n  }\n  return "Medium"\n}', tests: [{ input: ["abc"], expected: "Weak" }, { input: ["abcdef"], expected: "Medium" }, { input: ["abcdefghij"], expected: "Medium" }, { input: ["abcdefghij!"], expected: "Strong" }], hints: ["Length pehle check karo", "Special char ke liye regex use karo"] },
  { id: "04-01-23", title: "Switch se month ke days batao", starterCode: '// function daysInMonth(month) mein number 1-12 do\n// 31: Jan, Mar, May, Jul, Aug, Oct, Dec\n// 30: Apr, Jun, Sep, Nov\n// 28: Feb\n', solution: 'function daysInMonth(month) {\n  switch (month) {\n    case 1: case 3: case 5: case 7: case 8: case 10: case 12: return 31\n    case 4: case 6: case 9: case 11: return 30\n    case 2: return 28\n    default: return -1\n  }\n}', tests: [{ input: [1], expected: 31 }, { input: [4], expected: 30 }, { input: [2], expected: 28 }, { input: [13], expected: -1 }], hints: ["Fall-through se same days wale months group karo", "Default mein -1 return karo invalid month ke liye"] },
  { id: "04-01-24", title: "Nested if se electricity bill", starterCode: '// function electricityBill(units) mein units do\n// <=100: free, 101-300: Rs.5/unit, 301-500: Rs.8/unit, >500: Rs.10/unit\n// Total bill return karo\n', solution: 'function electricityBill(units) {\n  if (units <= 100) return 0\n  else if (units <= 300) return (units - 100) * 5\n  else if (units <= 500) return 200 * 5 + (units - 300) * 8\n  else return 200 * 5 + 200 * 8 + (units - 500) * 10\n}', tests: [{ input: [50], expected: 0 }, { input: [200], expected: 500 }, { input: [400], expected: 1800 }, { input: [600], expected: 3800 }], hints: ["Slab based billing hai — cumulative calculate karo", "Har slab ka alag rate hai"] },
  { id: "04-01-25", title: "Guard clause se array validate karo", starterCode: '// function sumArray(arr) mein array do\n// Agar array nahi hai ya empty hai: "Invalid array"\n// Agar koi non-number element hai: "Array must contain only numbers"\n// Warna sum return karo\n', solution: 'function sumArray(arr) {\n  if (!Array.isArray(arr) || arr.length === 0) return "Invalid array"\n  if (arr.some(item => typeof item !== "number" || Number.isNaN(item))) return "Array must contain only numbers"\n  return arr.reduce((acc, n) => acc + n, 0)\n}', tests: [{ input: [[1, 2, 3]], expected: 6 }, { input: [[]], expected: "Invalid array" }, { input: ["not array"], expected: "Invalid array" }, { input: [1, "two", 3], expected: "Array must contain only numbers" }], hints: ["Pehle array type check karo", "Phir elements ka type check karo"] },
  { id: "04-01-26", title: "Nested ternary se grade batao", starterCode: '// function gradeFromScore(score) mein number do\n// >=90: "A", >=80: "B", >=70: "C", >=60: "D", <60: "F"\n// Nested ternary operator use karo\n', solution: 'function gradeFromScore(score) {\n  return score >= 90 ? "A" : score >= 80 ? "B" : score >= 70 ? "C" : score >= 60 ? "D" : "F"\n}', tests: [{ input: [95], expected: "A" }, { input: [85], expected: "B" }, { input: [75], expected: "C" }, { input: [65], expected: "D" }, { input: [50], expected: "F" }], hints: ["condition ? true : false syntax use karo", "Nested ternary ek line mein chalta hai"] },
  { id: "04-01-27", title: "Switch se roman numeral banao", starterCode: '// function toRoman(num) mein number 1-10 do\n// 1: "I", 2: "II", ..., 10: "X"\n', solution: 'function toRoman(num) {\n  switch (num) {\n    case 1: return "I"\n    case 2: return "II"\n    case 3: return "III"\n    case 4: return "IV"\n    case 5: return "V"\n    case 6: return "VI"\n    case 7: return "VII"\n    case 8: return "VIII"\n    case 9: return "IX"\n    case 10: return "X"\n    default: return "Invalid"\n  }\n}', tests: [{ input: [1], expected: "I" }, { input: [4], expected: "IV" }, { input: [9], expected: "IX" }, { input: [10], expected: "X" }], hints: ["Har number ka specific roman representation hai", "Switch default mein invalid return karo"] },
  { id: "04-01-28", title: "Nested if se triangle type check", starterCode: '// function triangleType(a, b, c) mein teen sides do\n// Invalid triangle: "Not a triangle"\n// All equal: "Equilateral"\n// Two equal: "Isosceles"\n// All different: "Scalene"\n', solution: 'function triangleType(a, b, c) {\n  if (a <= 0 || b <= 0 || c <= 0) return "Not a triangle"\n  if (a + b <= c || a + c <= b || b + c <= a) return "Not a triangle"\n  if (a === b && b === c) return "Equilateral"\n  else if (a === b || b === c || a === c) return "Isosceles"\n  else return "Scalene"\n}', tests: [{ input: [3, 3, 3], expected: "Equilateral" }, { input: [3, 3, 5], expected: "Isosceles" }, { input: [3, 4, 5], expected: "Scalene" }, { input: [1, 2, 10], expected: "Not a triangle" }], hints: ["Triangle inequality theorem check karo", "Sum of two sides > third side hona chahiye"] },
  { id: "04-01-29", title: "Switch se simple calculator with chain", starterCode: '// function calc(a, op, b) mein do numbers aur operator do\n// "+", "-", "*", "/" ke liye calculate karo\n// Division by zero handle karo\n', solution: 'function calc(a, op, b) {\n  switch (op) {\n    case "+": return a + b\n    case "-": return a - b\n    case "*": return a * b\n    case "/":\n      if (b === 0) return "Cannot divide by zero"\n      return a / b\n    default: return "Invalid operator"\n  }\n}', tests: [{ input: [15, "+", 5], expected: 20 }, { input: [15, "-", 5], expected: 10 }, { input: [15, "*", 3], expected: 45 }, { input: [15, "/", 0], expected: "Cannot divide by zero" }], hints: ["Switch ke andar bhi if use kar sakte ho", "Case "/" mein division by zero check karo"] },
  { id: "04-01-30", title: "Nested if seLeap year check", starterCode: '// function isLeapYear(year) mein year do\n// divisible by 400: true\n// divisible by 100 but not 400: false\n// divisible by 4 but not 100: true\n// Baaki: false\n', solution: 'function isLeapYear(year) {\n  if (year % 400 === 0) return true\n  if (year % 100 === 0) return false\n  if (year % 4 === 0) return true\n  return false\n}', tests: [{ input: [2000], expected: true }, { input: [1900], expected: false }, { input: [2024], expected: true }, { input: [2023], expected: false }], hints: ["400 sabse pehle check karo", "Phir 100 check karo", "Phir 4 check karo"] },
  { id: "04-01-31", title: "Guard clause se object validate karo", starterCode: '// function getUserName(user) mein object do\n// Agar user null/undefined hai: "No user"\n// Agar name nahi hai: "No name"\n// Warna user.name return karo\n', solution: 'function getUserName(user) {\n  if (!user) return "No user"\n  if (!user.name) return "No name"\n  return user.name\n}', tests: [{ input: [{ name: "Hariom" }], expected: "Hariom" }, { input: [null], expected: "No user" }, { input: [undefined], expected: "No user" }, { input: [{}], expected: "No name" }], hints: ["!user se null/undefined dono check hote hain", "Guard clause se nesting bachao"] },
  { id: "04-01-32", title: "Nested if se shipping cost", starterCode: '// function shippingCost(weight, isExpress)\n// <=1kg: 50, <=5kg: 100, >5kg: 200\n// Express hai to 2x charge karo\n', solution: 'function shippingCost(weight, isExpress) {\n  let cost\n  if (weight <= 1) cost = 50\n  else if (weight <= 5) cost = 100\n  else cost = 200\n  return isExpress ? cost * 2 : cost\n}', tests: [{ input: [0.5, false], expected: 50 }, { input: [3, false], expected: 100 }, { input: [10, false], expected: 200 }, { input: [0.5, true], expected: 100 }], hints: ["Pehle weight se cost nikalo", "Phir express check karke multiply karo"] },
  { id: "04-01-33", title: "Switch se day type batao", starterCode: '// function dayType(day) mein string day name do\n// "Monday"-"Friday": "Weekday", "Saturday","Sunday": "Weekend"\n// Invalid: "Invalid day"\n', solution: 'function dayType(day) {\n  switch (day.toLowerCase()) {\n    case "monday": case "tuesday": case "wednesday": case "thursday": case "friday":\n      return "Weekday"\n    case "saturday": case "sunday":\n      return "Weekend"\n    default:\n      return "Invalid day"\n  }\n}', tests: [{ input: ["Monday"], expected: "Weekday" }, { input: ["Friday"], expected: "Weekday" }, { input: ["Saturday"], expected: "Weekend" }, { input: ["Funday"], expected: "Invalid day" }], hints: ["Fall-through se weekdays group karo", "toLowerCase se case-insensitive karo"] },
  { id: "04-01-34", title: "Nested if se number properties", starterCode: '// function numberProps(num) mein number do\n// Return: { isPositive, isEven, isMultipleOf3 }\n', solution: 'function numberProps(num) {\n  return {\n    isPositive: num > 0,\n    isEven: num % 2 === 0,\n    isMultipleOf3: num % 3 === 0\n  }\n}', tests: [{ input: [6], expected: { isPositive: true, isEven: true, isMultipleOf3: true } }, { input: [-3], expected: { isPositive: false, isEven: false, isMultipleOf3: true } }, { input: [7], expected: { isPositive: true, isEven: false, isMultipleOf3: false } }], hints: ["Ternary operator se boolean values banao", "Modulo se even/multiple check karo"] },
  { id: "04-01-35", title: "Guard clause se array access", starterCode: '// function getElement(arr, index) mein array aur index do\n// Agar array nahi hai: "Invalid array"\n// Agar index out of bounds: "Index out of bounds"\n// Warna element return karo\n', solution: 'function getElement(arr, index) {\n  if (!Array.isArray(arr)) return "Invalid array"\n  if (index < 0 || index >= arr.length) return "Index out of bounds"\n  return arr[index]\n}', tests: [{ input: [[10, 20, 30], 1], expected: 20 }, { input: [[10, 20, 30], 5], expected: "Index out of bounds" }, { input: [null, 0], expected: "Invalid array" }, { input: [[10, 20, 30], -1], expected: "Index out of bounds" }], hints: ["Array.isArray() se array type check karo", "Index < 0 ya >= length ho to error"] },
  { id: "04-01-36", title: "Nested if se complex condition", starterCode: '// function canRide(height, age, hasHelmet)\n// height >= 120 aur age >= 12: "Can ride"\n// height >= 120 aur age < 12 aur hasHelmet: "Can ride with helmet"\n// height < 120: "Too short"\n// Baaki: "Cannot ride"\n', solution: 'function canRide(height, age, hasHelmet) {\n  if (height < 120) return "Too short"\n  if (age >= 12) return "Can ride"\n  if (hasHelmet) return "Can ride with helmet"\n  return "Cannot ride"\n}', tests: [{ input: [130, 15, false], expected: "Can ride" }, { input: [130, 10, true], expected: "Can ride with helmet" }, { input: [110, 15, false], expected: "Too short" }, { input: [130, 10, false], expected: "Cannot ride" }], hints: ["Pehle height check karo — sabse strict condition", "Phir age, phir helmet"] },
  { id: "04-01-37", title: "Switch se grade points mapping", starterCode: '// function gradePoints(grade) mein grade string do\n// "A+": 4.0, "A": 3.7, "B+": 3.3, "B": 3.0, "C": 2.0, "F": 0.0\n// Invalid grade: -1\n', solution: 'function gradePoints(grade) {\n  switch (grade) {\n    case "A+": return 4.0\n    case "A": return 3.7\n    case "B+": return 3.3\n    case "B": return 3.0\n    case "C": return 2.0\n    case "F": return 0.0\n    default: return -1\n  }\n}', tests: [{ input: ["A+"], expected: 4.0 }, { input: ["B"], expected: 3.0 }, { input: ["F"], expected: 0.0 }, { input: ["D"], expected: -1 }], hints: ["Har grade ka specific GPA value hai", "Default mein -1 return karo"] },
  { id: "04-01-38", title: "Nested if se age-based restrictions", starterCode: '// function ageRestriction(age)\n// < 13: "No social media", 13-17: "Parental consent needed", 18-64: "Full access", 65+: "Easy mode"\n', solution: 'function ageRestriction(age) {\n  if (age < 13) return "No social media"\n  else if (age < 18) return "Parental consent needed"\n  else if (age <= 64) return "Full access"\n  else return "Easy mode"\n}', tests: [{ input: [10], expected: "No social media" }, { input: [15], expected: "Parental consent needed" }, { input: [30], expected: "Full access" }, { input: [70], expected: "Easy mode" }], hints: ["Sabse pehle chhoti age check karo", "Else if chain se ranges handle karo"] },
  { id: "04-01-39", title: "Switch se Vowel ya Consonant", starterCode: '// function isVowel(char) mein single character do\n// Vowel: true, Consonant: false, Not letter: null\n', solution: 'function isVowel(char) {\n  const lower = char.toLowerCase()\n  switch (lower) {\n    case "a": case "e": case "i": case "o": case "u":\n      return true\n    default:\n      if (lower >= "a" && lower <= "z") return false\n      return null\n  }\n}', tests: [{ input: ["a"], expected: true }, { input: ["A"], expected: true }, { input: ["b"], expected: false }, { input: ["1"], expected: null }], hints: ["Switch se vowels check karo", "Default mein letter hai ya nahi check karo"] },
  { id: "04-01-40", title: "Guard clause se nested object access", starterCode: '// function getCity(user) mein object do\n// Safe access karo: user.address.city\n// Agar kuch bhi missing hai: "Unknown"\n', solution: 'function getCity(user) {\n  if (!user) return "Unknown"\n  if (!user.address) return "Unknown"\n  if (!user.address.city) return "Unknown"\n  return user.address.city\n}', tests: [{ input: [{ address: { city: "Jaipur" } }], expected: "Jaipur" }, { input: [{ address: {} }], expected: "Unknown" }, { input: [{}], expected: "Unknown" }, { input: [null], expected: "Unknown" }], hints: ["Har level pe null check karo", "Guard clause pattern se optional chaining jaisa kaam hota hai"] },
  { id: "04-01-41", title: "Nested if se discount tiers", starterCode: '// function tierDiscount(amount)\n// < 1000: 5%, 1000-4999: 10%, 5000-9999: 15%, >=10000: 20%\n// Discounted amount return karo\n', solution: 'function tierDiscount(amount) {\n  let discount\n  if (amount < 1000) discount = 0.05\n  else if (amount < 5000) discount = 0.10\n  else if (amount < 10000) discount = 0.15\n  else discount = 0.20\n  return amount - (amount * discount)\n}', tests: [{ input: [500], expected: 475 }, { input: [2000], expected: 1800 }, { input: [7000], expected: 5950 }, { input: [15000], expected: 12000 }], hints: ["Har range ka alag discount percentage hai", "Final amount = amount - (amount * discount/100)"] },
  { id: "04-01-42", title: "Switch se direction vector", starterCode: '// function directionVector(dir) mein string do\n// "up": [0,1], "down": [0,-1], "left": [-1,0], "right": [1,0]\n// Invalid: null\n', solution: 'function directionVector(dir) {\n  switch (dir) {\n    case "up": return [0, 1]\n    case "down": return [0, -1]\n    case "left": return [-1, 0]\n    case "right": return [1, 0]\n    default: return null\n  }\n}', tests: [{ input: ["up"], expected: [0, 1] }, { input: ["down"], expected: [0, -1] }, { input: ["left"], expected: [-1, 0] }, { input: ["right"], expected: [1, 0] }, { input: ["diagonal"], expected: null }], hints: ["Har direction ka [x,y] pair hai", "Default mein null return karo"] },
  { id: "04-01-43", title: "Nested if se eligibility check", starterCode: '// function canApply(age, income, isStudent)\n// Student aur <30: "Student discount"\n// Income < 300000: "Low income benefit"\n// Age > 60: "Senior citizen benefit"\n// Baaki: "No special benefit"\n', solution: 'function canApply(age, income, isStudent) {\n  if (isStudent && age < 30) return "Student discount"\n  if (income < 300000) return "Low income benefit"\n  if (age > 60) return "Senior citizen benefit"\n  return "No special benefit"\n}', tests: [{ input: [22, 100000, true], expected: "Student discount" }, { input: [25, 200000, false], expected: "Low income benefit" }, { input: [65, 500000, false], expected: "Senior citizen benefit" }, { input: [35, 500000, false], expected: "No special benefit" }], hints: ["Pehle combined condition check karo", "Guard clause pattern use karo"] },
  { id: "04-01-44", title: "Switch se currency symbol", starterCode: '// function currencySymbol(code) mein string code do\n// "INR": "₹", "USD": "$", "EUR": "€", "GBP": "£"\n// Unknown: "?"\n', solution: 'function currencySymbol(code) {\n  switch (code.toUpperCase()) {\n    case "INR": return "₹"\n    case "USD": return "$"\n    case "EUR": return "€"\n    case "GBP": return "£"\n    default: return "?"\n  }\n}', tests: [{ input: ["INR"], expected: "₹" }, { input: ["usd"], expected: "$" }, { input: ["eur"], expected: "€" }, { input: ["jpy"], expected: "?" }], hints: ["toUpperCase se case-insensitive comparison hota hai", "Default case mein ? return karo"] },
  { id: "04-01-45", title: "Nested if se priority check", starterCode: '// function priority(score, isUrgent)\n// Score >= 90: "Critical"\n// Score >= 70 aur urgent: "High"\n// Score >= 70: "Medium"\n// Score < 70 aur urgent: "Low-Urgent"\n// Baaki: "Low"\n', solution: 'function priority(score, isUrgent) {\n  if (score >= 90) return "Critical"\n  if (score >= 70 && isUrgent) return "High"\n  if (score >= 70) return "Medium"\n  if (isUrgent) return "Low-Urgent"\n  return "Low"\n}', tests: [{ input: [95, false], expected: "Critical" }, { input: [75, true], expected: "High" }, { input: [75, false], expected: "Medium" }, { input: [50, true], expected: "Low-Urgent" }, { input: [50, false], expected: "Low" }], hints: ["Score aur urgency dono alag check hote hain", "Order mein priority set karo"] },
  { id: "04-01-46", title: "Guard clause se user profile", starterCode: '// function getFullName(user) mein object do\n// Agar user nahi: "Unknown user"\n// Agar first name nahi: "Unknown first name"\n// Agar last name nahi: "Unknown last name"\n// Warna "First Last" return karo\n', solution: 'function getFullName(user) {\n  if (!user) return "Unknown user"\n  if (!user.firstName) return "Unknown first name"\n  if (!user.lastName) return "Unknown last name"\n  return `${user.firstName} ${user.lastName}`\n}', tests: [{ input: [{ firstName: "Hariom", lastName: "Verma" }], expected: "Hariom Verma" }, { input: [null], expected: "Unknown user" }, { input: [{ lastName: "Verma" }], expected: "Unknown first name" }, { input: [{ firstName: "Hariom" }], expected: "Unknown last name" }], hints: ["Har missing property ke liye alag error message do", "Guard clause se pehle pehle check karo"] },
  { id: "04-01-47", title: "Switch se simple encryption", starterCode: '// function encrypt(char) mein single character do\n// A->Z, B->Y, C->X ... Z->A (reverse alphabet)\n// Non-letter: same return karo\n', solution: 'function encrypt(char) {\n  const lower = char.toLowerCase()\n  if (lower >= "a" && lower <= "z") {\n    const code = lower.charCodeAt(0)\n    const encrypted = String.fromCharCode(122 - code + 97)\n    return char === char.toUpperCase() ? encrypted.toUpperCase() : encrypted\n  }\n  return char\n}', tests: [{ input: ["A"], expected: "Z" }, { input: ["b"], expected: "y" }, { input: ["M"], expected: "N" }, { input: ["1"], expected: "1" }], hints: ["charCodeAt se ASCII code milta hai", "122 = 'z' ka code, 97 = 'a' ka code"] },
  { id: "04-01-48", title: "Nested if se complex validation", starterCode: '// function validateAgeGender(age, gender)\n// Age < 0 ya > 150: "Invalid age"\n// Gender "M"/"F"/"Other": valid\n// Baaki: "Invalid gender"\n// Sab valid: "Valid"\n', solution: 'function validateAgeGender(age, gender) {\n  if (age < 0 || age > 150) return "Invalid age"\n  if (gender !== "M" && gender !== "F" && gender !== "Other") return "Invalid gender"\n  return "Valid"\n}', tests: [{ input: [25, "M"], expected: "Valid" }, { input: [-5, "M"], expected: "Invalid age" }, { input: [25, "X"], expected: "Invalid gender" }, { input: [200, "F"], expected: "Invalid age" }], hints: ["Age range check pehle karo", "Gender sirf teen values accept karta hai"] },
  { id: "04-01-49", title: "Switch seHttpStatus message", starterCode: '// function httpMessage(code) mein status code do\n// 200: "OK", 201: "Created", 404: "Not Found", 500: "Server Error"\n// Unknown code: "Unknown"\n', solution: 'function httpMessage(code) {\n  switch (code) {\n    case 200: return "OK"\n    case 201: return "Created"\n    case 404: return "Not Found"\n    case 500: return "Server Error"\n    default: return "Unknown"\n  }\n}', tests: [{ input: [200], expected: "OK" }, { input: [201], expected: "Created" }, { input: [404], expected: "Not Found" }, { input: [500], expected: "Server Error" }, { input: [418], expected: "Unknown" }], hints: ["HTTP status codes ke liye switch perfect hai", "Default case mein Unknown return karo"] },
  { id: "04-01-50", title: "Nested if se final complex problem", starterCode: '// function processOrder(quantity, price, isMember)\n// quantity <= 0 ya price <= 0: "Invalid order"\n// Total = quantity * price\n// Member: 20% discount\n// Total > 5000: extra 5% discount\n// Final total return karo\n', solution: 'function processOrder(quantity, price, isMember) {\n  if (quantity <= 0 || price <= 0) return "Invalid order"\n  let total = quantity * price\n  if (isMember) total *= 0.8\n  if (total > 5000) total *= 0.95\n  return total\n}', tests: [{ input: [10, 100, true], expected: 800 }, { input: [100, 100, true], expected: 7600 }, { input: [100, 100, false], expected: 9500 }, { input: [0, 100, false], expected: "Invalid order" }], hints: ["Pehle input validation karo", "Phir member discount, phir bulk discount apply karo"] },
])

// 04-02: early-return (50 exercises)
writeLesson("04-control-flow", 1, "early-return", [
  { id: "04-02-01", title: "Null check with early return", starterCode: '// function greet(name) mein name do\n// Agar name null/undefined/empty hai: "Hello, Guest!"\n// Warna: "Hello, {name}!"\n', solution: 'function greet(name) {\n  if (!name) return "Hello, Guest!"\n  return `Hello, ${name}!`\n}', tests: [{ input: ["Hariom"], expected: "Hello, Hariom!" }, { input: [null], expected: "Hello, Guest!" }, { input: [undefined], expected: "Hello, Guest!" }, { input: [""], expected: "Hello, Guest!" }], hints: ["!name se null, undefined, empty string sab check hote hain", "Early return se nesting kam hoti hai"] },
  { id: "04-02-02", title: "Guard clause for array length", starterCode: '// function firstElement(arr) mein array do\n// Agar array empty ya invalid hai: null\n// Warna pehla element return karo\n', solution: 'function firstElement(arr) {\n  if (!Array.isArray(arr) || arr.length === 0) return null\n  return arr[0]\n}', tests: [{ input: [[1, 2, 3]], expected: 1 }, { input: [[]], expected: null }, { input: [null], expected: null }], hints: ["Array.isArray() pehle check karo", "Length zero hai to null return karo"] },
  { id: "04-02-03", title: "Early return for number validation", starterCode: '// function double(num) mein number do\n// Agar number nahi hai: null\n// Warna double return karo\n', solution: 'function double(num) {\n  if (typeof num !== "number" || Number.isNaN(num)) return null\n  return num * 2\n}', tests: [{ input: [5], expected: 10 }, { input: [-3], expected: -6 }, { input: ["hello"], expected: null }, { input: [NaN], expected: null }], hints: ["typeof check se type validate hota hai", "NaN bhi special case hai"] },
  { id: "04-02-04", title: "Guard clause for string processing", starterCode: '// function capitalize(str) mein string do\n// Agar string nahi hai ya empty: ""\n// Warna pehla character uppercase, baaki lowercase\n', solution: 'function capitalize(str) {\n  if (typeof str !== "string" || str.length === 0) return ""\n  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase()\n}', tests: [{ input: ["hello"], expected: "Hello" }, { input: ["HELLO"], expected: "Hello" }, { input: [""], expected: "" }, { input: [null], expected: "" }], hints: ["charAt(0) se pehla character milta hai", "slice(1) se baaki string milti hai"] },
  { id: "04-02-05", title: "Multiple guard clauses", starterCode: '// function divide(a, b) mein do numbers do\n// Agar a number nahi: "Invalid numerator"\n// Agar b number nahi: "Invalid denominator"\n// Agar b === 0: "Cannot divide by zero"\n// Warna result return karo\n', solution: 'function divide(a, b) {\n  if (typeof a !== "number") return "Invalid numerator"\n  if (typeof b !== "number") return "Invalid denominator"\n  if (b === 0) return "Cannot divide by zero"\n  return a / b\n}', tests: [{ input: [10, 2], expected: 5 }, { input: ["ten", 2], expected: "Invalid numerator" }, { input: [10, "two"], expected: "Invalid denominator" }, { input: [10, 0], expected: "Cannot divide by zero" }], hints: ["Har input ke liye alag guard clause likho", "Pehle types validate karo phir operation karo"] },
  { id: "04-02-06", title: "Default parameter with guard", starterCode: '// function createUser(name, age = 18, city = "Unknown")\n// Agar name falsy hai: "Name is required"\n// Warna { name, age, city } return karo\n', solution: 'function createUser(name, age = 18, city = "Unknown") {\n  if (!name) return "Name is required"\n  return { name, age, city }\n}', tests: [{ input: ["Hariom", 25, "Jaipur"], expected: { name: "Hariom", age: 25, city: "Jaipur" } }, { input: ["Amit"], expected: { name: "Amit", age: 18, city: "Unknown" } }, { input: [""], expected: "Name is required" }], hints: ["Default parameters se missing values handle hoti hain", "Guard clause se required fields validate karo"] },
  { id: "04-02-07", title: "Early return for object property", starterCode: '// function getPrice(product) mein object do\n// Agar product ya product.price nahi: 0\n// Warna product.price return karo\n', solution: 'function getPrice(product) {\n  if (!product || typeof product.price !== "number") return 0\n  return product.price\n}', tests: [{ input: [{ name: "Item", price: 100 }], expected: 100 }, { input: [{ name: "Item" }], expected: 0 }, { input: [null], expected: 0 }], hints: ["Optional chaining jaisa guard clause use karo", "typeof se number type verify karo"] },
  { id: "04-02-08", title: "Guard clause for email validation", starterCode: '// function isValidEmail(email) mein string do\n// Agar string nahi ya empty: false\n// Agar @ nahi hai: false\n// Agar . nahi hai @ ke baad: false\n// Warna true\n', solution: 'function isValidEmail(email) {\n  if (typeof email !== "string" || email.length === 0) return false\n  if (!email.includes("@")) return false\n  const afterAt = email.split("@")[1]\n  if (!afterAt || !afterAt.includes(".")) return false\n  return true\n}', tests: [{ input: ["test@test.com"], expected: true }, { input: ["invalid"], expected: false }, { input: [""], expected: false }, { input: ["test@"], expected: false }], hints: ["Pehle type check karo", "Phir @ aur . check karo"] },
  { id: "04-02-09", title: "Chained validation with guards", starterCode: '// function processAge(age)\n// String hai to parseFloat karo\n// Number nahi hai: "Invalid age"\n// < 0: "Age cannot be negative"\n// > 150: "Age too high"\n// Warna number return karo\n', solution: 'function processAge(age) {\n  if (typeof age === "string") age = parseFloat(age)\n  if (typeof age !== "number" || Number.isNaN(age)) return "Invalid age"\n  if (age < 0) return "Age cannot be negative"\n  if (age > 150) return "Age too high"\n  return age\n}', tests: [{ input: [25], expected: 25 }, { input: ["30"], expected: 30 }, { input: ["abc"], expected: "Invalid age" }, { input: [-5], expected: "Age cannot be negative" }, { input: [200], expected: "Age too high" }], hints: ["String ko number mein convert karo pehle", "Phir har validation ke liye early return karo"] },
  { id: "04-02-10", title: "API response handler with guards", starterCode: '// function extractData(response)\n// Agar response null: "No response"\n// Agar response.ok nahi: "Request failed"\n// Agar response.data nahi: "No data"\n// Warna response.data return karo\n', solution: 'function extractData(response) {\n  if (!response) return "No response"\n  if (!response.ok) return "Request failed"\n  if (!response.data) return "No data"\n  return response.data\n}', tests: [{ input: [{ ok: true, data: { users: [] } }], expected: { users: [] } }, { input: [{ ok: false, error: "404" }], expected: "Request failed" }, { input: [{ ok: true }], expected: "No data" }, { input: [null], expected: "No response" }], hints: ["Har level pe ek ek guard clause lagao", "Pehle existence, phir value check karo"] },
  { id: "04-02-11", title: "Permission guard pattern", starterCode: '// function deleteUser(user, targetId)\n// Agar user nahi: "No user"\n// Agar user.admin nahi: "Not authorized"\n// Agar targetId same hai user.id: "Cannot delete self"\n// Warna "Deleted {targetId}"\n', solution: 'function deleteUser(user, targetId) {\n  if (!user) return "No user"\n  if (!user.admin) return "Not authorized"\n  if (targetId === user.id) return "Cannot delete self"\n  return `Deleted ${targetId}`\n}', tests: [{ input: [{ id: 1, admin: true }, 2], expected: "Deleted 2" }, { input: [null, 2], expected: "No user" }, { input: [{ id: 1, admin: false }, 2], expected: "Not authorized" }, { input: [{ id: 1, admin: true }, 1], expected: "Cannot delete self" }], hints: ["Har permission check ke liye early return karo", "Authorization pehle, operation baad mein"] },
  { id: "04-02-12", title: "Guard clause for input sanitization", starterCode: '// function sanitizeInput(input)\n// Agar string nahi: ""\n// Trim karo\n// Empty hai to: ""\n// Warna lowercase return karo\n', solution: 'function sanitizeInput(input) {\n  if (typeof input !== "string") return ""\n  const trimmed = input.trim()\n  if (trimmed.length === 0) return ""\n  return trimmed.toLowerCase()\n}', tests: [{ input: ["  Hello World  "], expected: "hello world" }, { input: ["  "], expected: "" }, { input: [123], expected: "" }, { input: [null], expected: "" }], hints: ["typeof se string type check karo", "Trim se spaces hati hain"] },
  { id: "04-02-13", title: "Array processing with guard", starterCode: '// function sumPositive(arr) mein array do\n// Agar array nahi ya empty: 0\n// Agar koi non-number hai: "Invalid element"\n// Warna sirf positive numbers ka sum do\n', solution: 'function sumPositive(arr) {\n  if (!Array.isArray(arr) || arr.length === 0) return 0\n  if (arr.some(item => typeof item !== "number")) return "Invalid element"\n  return arr.filter(n => n > 0).reduce((acc, n) => acc + n, 0)\n}', tests: [{ input: [[1, -2, 3, -4, 5]], expected: 9 }, { input: [[]], expected: 0 }, { input: [[1, "two", 3]], expected: "Invalid element" }], hints: ["filter se positive numbers alag karo", "reduce se sum nikalo"] },
  { id: "04-02-14", title: "Object property access guard", starterCode: '// function getNestedValue(obj, path) mein object aur path array do\n// Agar obj nahi: undefined\n// Path pehle-pehle traverse karo\n// Agar kahi undefined mila: undefined\n// Warna final value return karo\n', solution: 'function getNestedValue(obj, path) {\n  if (!obj || !Array.isArray(path)) return undefined\n  let current = obj\n  for (const key of path) {\n    if (current === null || current === undefined) return undefined\n    current = current[key]\n  }\n  return current\n}', tests: [{ input: [{ a: { b: { c: 42 } } }, ["a", "b", "c"]], expected: 42 }, { input: [{ a: { b: 1 } }, ["a", "x"]], expected: undefined }, { input: [null, ["a"]], expected: undefined }], hints: ["Har step pe null/undefined check karo", "Loop se path traverse karo"] },
  { id: "04-02-15", title: "Type checking guard pattern", starterCode: '// function add(a, b) mein do values do\n// Agar dono numbers nahi: "Both must be numbers"\n// Agar sirf a number nahi: "First must be a number"\n// Agar sirf b number nahi: "Second must be a number"\n// Warna sum return karo\n', solution: 'function add(a, b) {\n  if (typeof a !== "number" && typeof b !== "number") return "Both must be numbers"\n  if (typeof a !== "number") return "First must be a number"\n  if (typeof b !== "number") return "Second must be a number"\n  return a + b\n}', tests: [{ input: [5, 3], expected: 8 }, { input: ["five", 3], expected: "First must be a number" }, { input: [5, "three"], expected: "Second must be a number" }, { input: ["five", "three"], expected: "Both must be numbers" }], hints: ["Pehle dono check karo, phir ek ek karke check karo", "Error messages specific honi chahiye"] },
  { id: "04-02-16", title: "Boundary check with guard", starterCode: '// function setScore(score) mein number do\n// < 0: "Score cannot be negative"\n// > 100: "Score cannot exceed 100"\n// Warna score return karo\n', solution: 'function setScore(score) {\n  if (typeof score !== "number" || Number.isNaN(score)) return "Invalid score"\n  if (score < 0) return "Score cannot be negative"\n  if (score > 100) return "Score cannot exceed 100"\n  return score\n}', tests: [{ input: [75], expected: 75 }, { input: [-5], expected: "Score cannot be negative" }, { input: [105], expected: "Score cannot exceed 100" }, { input: [NaN], expected: "Invalid score" }], hints: ["Pehle type check karo", "Phir boundary values check karo"] },
  { id: "04-02-17", title: "Function composition with guards", starterCode: '// function pipe(value, ...fns) mein value aur functions do\n// Agar value null/undefined hai: value return karo\n// Agar fns empty hai: value return karo\n// Warna har function se pass karo\n', solution: 'function pipe(value, ...fns) {\n  if (value === null || value === undefined) return value\n  if (fns.length === 0) return value\n  return fns.reduce((acc, fn) => fn(acc), value)\n}', tests: [{ input: [5, x => x * 2, x => x + 1], expected: 11 }, { input: [null, x => x * 2], expected: null }, { input: [5], expected: 5 }], hints: ["Reduce se functions ek ek apply hoti hain", "Null/undefined pe seedha return karo"] },
  { id: "04-02-18", title: "Complex condition simplification", starterCode: '// function canPurchase(age, income, hasCriminalRecord)\n// Criminal record: false\n// Age < 18: false\n// Income < 0: false\n// Baaki: true\n', solution: 'function canPurchase(age, income, hasCriminalRecord) {\n  if (hasCriminalRecord) return false\n  if (age < 18) return false\n  if (income < 0) return false\n  return true\n}', tests: [{ input: [25, 50000, false], expected: true }, { input: [15, 50000, false], expected: false }, { input: [25, -100, false], expected: false }, { input: [25, 50000, true], expected: false }], hints: ["Har rejection condition ke liye early return false karo", "Last mein true return karo"] },
  { id: "04-02-19", title: "Guard for array operations", starterCode: '// function getMax(arr) mein array do\n// Agar array nahi ya empty: null\n// Agar koi non-number: "Invalid element"\n// Warna maximum value do\n', solution: 'function getMax(arr) {\n  if (!Array.isArray(arr) || arr.length === 0) return null\n  if (arr.some(item => typeof item !== "number")) return "Invalid element"\n  return Math.max(...arr)\n}', tests: [{ input: [[3, 1, 4, 1, 5, 9]], expected: 9 }, { input: [[]], expected: null }, { input: [[1, "two", 3]], expected: "Invalid element" }], hints: ["Spread operator se array Math.max mein pass hota hai", "Guard clause pehle array validate karo"] },
  { id: "04-02-20", title: "Early return for async-like pattern", starterCode: '// function fetchData(config)\n// Agar config nahi: "No config"\n// Agar config.url nahi: "No URL"\n// Agar config.method nahi: "No method"\n// Warna { url, method, headers } return karo\n', solution: 'function fetchData(config) {\n  if (!config) return "No config"\n  if (!config.url) return "No URL"\n  if (!config.method) return "No method"\n  return {\n    url: config.url,\n    method: config.method,\n    headers: config.headers || {}\n  }\n}', tests: [{ input: [{ url: "/api", method: "GET" }], expected: { url: "/api", method: "GET", headers: {} } }, { input: [{ method: "GET" }], expected: "No URL" }, { input: [null], expected: "No config" }], hints: ["Config object ke har required property check karo", "Default values se fallback handle karo"] },
  { id: "04-02-21", title: "Guard clause for number range", starterCode: '// function classify(n) mein number do\n// < 0: "negative", 0: "zero", 1-10: "small", 11-100: "medium", >100: "large"\n// Non-number: "not a number"\n', solution: 'function classify(n) {\n  if (typeof n !== "number" || Number.isNaN(n)) return "not a number"\n  if (n < 0) return "negative"\n  if (n === 0) return "zero"\n  if (n <= 10) return "small"\n  if (n <= 100) return "medium"\n  return "large"\n}', tests: [{ input: [-5], expected: "negative" }, { input: [0], expected: "zero" }, { input: [5], expected: "small" }, { input: [50], expected: "medium" }, { input: [200], expected: "large" }, { input: ["abc"], expected: "not a number" }], hints: ["Type check pehle karo", "Ranges ascending mein check karo"] },
  { id: "04-02-22", title: "Chained guards for object creation", starterCode: '// function createProduct(name, price, category)\n// Name empty: "Name required"\n// Price <= 0: "Invalid price"\n// Category empty: "Category required"\n// Warna product object return karo\n', solution: 'function createProduct(name, price, category) {\n  if (!name || name.trim().length === 0) return "Name required"\n  if (typeof price !== "number" || price <= 0) return "Invalid price"\n  if (!category || category.trim().length === 0) return "Category required"\n  return { name: name.trim(), price, category: category.trim() }\n}', tests: [{ input: ["Laptop", 50000, "Electronics"], expected: { name: "Laptop", price: 50000, category: "Electronics" } }, { input: ["", 50000, "Electronics"], expected: "Name required" }, { input: ["Laptop", -100, "Electronics"], expected: "Invalid price" }, { input: ["Laptop", 50000, ""], expected: "Category required" }], hints: ["Har field ke liye alag guard clause", "Trim se whitespace validate hota hai"] },
  { id: "04-02-23", title: "Guard for string operations", starterCode: '// function countVowels(str) mein string do\n// Agar string nahi: -1\n// Warna vowels count karo\n', solution: 'function countVowels(str) {\n  if (typeof str !== "string") return -1\n  return str.toLowerCase().split("").filter(c => "aeiou".includes(c)).length\n}', tests: [{ input: ["Hello World"], expected: 3 }, { input: ["AEIOU"], expected: 5 }, { input: ["bcdfg"], expected: 0 }, { input: [123], expected: -1 }], hints: ["toLowerCase se case-insensitive counting hoti hai", "filter se sirf vowels alag hoti hain"] },
  { id: "04-02-24", title: "Guard for nested array", starterCode: '// function flatten(arr) mein nested array do\n// Agar array nahi: []\n// Agar koi element array nahi hai: "Invalid nested array"\n// Warna flat array do\n', solution: 'function flatten(arr) {\n  if (!Array.isArray(arr)) return []\n  if (arr.some(item => !Array.isArray(item))) return "Invalid nested array"\n  return arr.flat()\n}', tests: [{ input: [[1, 2], [3, 4]], expected: [1, 2, 3, 4] }, { input: ["not array"], expected: [] }, { input: [[1, 2], "invalid"], expected: "Invalid nested array" }], hints: ["Array.isArray() se type check hota hai", ".flat() se nested arrays flatten hoti hain"] },
  { id: "04-02-25", title: "Guard clause for data transformation", starterCode: '// function transformUser(user)\n// Agar user nahi: null\n// Agar user.name nahi: null\n// Warna { fullName, age } return karo\n', solution: 'function transformUser(user) {\n  if (!user) return null\n  if (!user.name) return null\n  return {\n    fullName: user.name.toUpperCase(),\n    age: user.age || 0\n  }\n}', tests: [{ input: [{ name: "hariom", age: 25 }], expected: { fullName: "HARIOM", age: 25 } }, { input: [{ name: "hariom" }], expected: { fullName: "HARIOM", age: 0 } }, { input: [null], expected: null }, { input: [{}], expected: null }], hints: ["Pehle existence check karo", "Default values se fallback do"] },
  { id: "04-02-26", title: "Guard for numeric string", starterCode: '// function toNumber(str) mein string do\n// Agar string nahi: null\n// Agar numeric nahi hai: NaN\n// Warna parseFloat return karo\n', solution: 'function toNumber(str) {\n  if (typeof str !== "string") return null\n  const num = parseFloat(str)\n  if (Number.isNaN(num)) return NaN\n  return num\n}', tests: [{ input: ["42"], expected: 42 }, { input: ["3.14"], expected: 3.14 }, { input: ["abc"], expected: NaN }, { input: [123], expected: null }], hints: ["typeof se string check karo", "parseFloat se number nikalo"] },
  { id: "04-02-27", title: "Guard for function arguments", starterCode: '// function mapArray(arr, fn) mein array aur function do\n// Agar array nahi: "Invalid array"\n// Agar function nahi: "Invalid function"\n// Warna map karo\n', solution: 'function mapArray(arr, fn) {\n  if (!Array.isArray(arr)) return "Invalid array"\n  if (typeof fn !== "function") return "Invalid function"\n  return arr.map(fn)\n}', tests: [{ input: [[1, 2, 3], x => x * 2], expected: [2, 4, 6] }, { input: ["not array", x => x], expected: "Invalid array" }, { input: [[1, 2], "not function"], expected: "Invalid function" }], hints: ["Array.isArray() se array check hota hai", "typeof function se function check hota hai"] },
  { id: "04-02-28", title: "Guard for boolean flag", starterCode: '// function toggleFeature(feature, enabled)\n// Agar feature nahi: "No feature specified"\n// Agar enabled boolean nahi: "Invalid flag"\n// Warna { feature, enabled } return karo\n', solution: 'function toggleFeature(feature, enabled) {\n  if (!feature) return "No feature specified"\n  if (typeof enabled !== "boolean") return "Invalid flag"\n  return { feature, enabled }\n}', tests: [{ input: ["darkMode", true], expected: { feature: "darkMode", enabled: true } }, { input: ["", true], expected: "No feature specified" }, { input: ["darkMode", "yes"], expected: "Invalid flag" }], hints: ["Feature ki existence check karo", "Enabled ka type boolean hona chahiye"] },
  { id: "04-02-29", title: "Guard for date validation", starterCode: '// function isValidDate(dateStr) mein string do "YYYY-MM-DD"\n// Agar string nahi: false\n// Format match nahi: false\n// Invalid date: false\n// Warna true\n', solution: 'function isValidDate(dateStr) {\n  if (typeof dateStr !== "string") return false\n  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false\n  const date = new Date(dateStr)\n  if (isNaN(date.getTime())) return false\n  return true\n}', tests: [{ input: ["2024-01-15"], expected: true }, { input: ["2024/01/15"], expected: false }, { input: ["invalid"], expected: false }, { input: [123], expected: false }], hints: ["Regex se format check karo", "new Date() se actual date validate karo"] },
  { id: "04-02-30", title: "Guard for password match", starterCode: '// function checkPassword(password, confirmPassword)\n// Password empty: "Password required"\n// Password < 6 chars: "Too short"\n// Confirm empty: "Confirmation required"\n// Dono match nahi: "Passwords do not match"\n// Warna "Password set successfully"\n', solution: 'function checkPassword(password, confirmPassword) {\n  if (!password) return "Password required"\n  if (password.length < 6) return "Too short"\n  if (!confirmPassword) return "Confirmation required"\n  if (password !== confirmPassword) return "Passwords do not match"\n  return "Password set successfully"\n}', tests: [{ input: ["secret123", "secret123"], expected: "Password set successfully" }, { input: ["", "secret123"], expected: "Password required" }, { input: ["abc", "abc"], expected: "Too short" }, { input: ["secret123", ""], expected: "Confirmation required" }, { input: ["secret123", "different"], expected: "Passwords do not match" }], hints: ["Har validation ke liye early return karo", "Order matters — pehle password, phir confirm"] },
  { id: "04-02-31", title: "Guard for array index access", starterCode: '// function safeGet(arr, index) mein array aur index do\n// Agar array nahi: undefined\n// Agar index out of bounds: undefined\n// Warna element return karo\n', solution: 'function safeGet(arr, index) {\n  if (!Array.isArray(arr)) return undefined\n  if (index < 0 || index >= arr.length) return undefined\n  return arr[index]\n}', tests: [{ input: [[10, 20, 30], 1], expected: 20 }, { input: [[10, 20, 30], 5], expected: undefined }, { input: [null, 0], expected: undefined }], hints: ["Array.isArray() pehle check karo", "Index boundary check karo dono taraf se"] },
  { id: "04-02-32", title: "Guard for string length", starterCode: '// function truncate(str, maxLen) mein string aur max length do\n// Agar string nahi: ""\n// Agar length <= maxLen: original string\n// Warna truncated string with "..." do\n', solution: 'function truncate(str, maxLen) {\n  if (typeof str !== "string") return ""\n  if (str.length <= maxLen) return str\n  return str.slice(0, maxLen) + "..."\n}', tests: [{ input: ["Hello World", 5], expected: "Hello..." }, { input: ["Hi", 10], expected: "Hi" }, { input: [null, 5], expected: "" }], hints: ["Slice se pehle maxLen characters lo", "... add karo end mein"] },
  { id: "04-02-33", title: "Guard for number operations", starterCode: '// function clamp(val, min, max) mein teen numbers do\n// Agar koi bhi non-number: null\n// Val < min: min, Val > max: max, Baaki: val\n', solution: 'function clamp(val, min, max) {\n  if (typeof val !== "number" || typeof min !== "number" || typeof max !== "number") return null\n  if (val < min) return min\n  if (val > max) return max\n  return val\n}', tests: [{ input: [5, 0, 10], expected: 5 }, { input: [-5, 0, 10], expected: 0 }, { input: [15, 0, 10], expected: 10 }, { input: ["a", 0, 10], expected: null }], hints: ["Teeno parameters ka type check karo", "Min/max boundaries enforce karo"] },
  { id: "04-02-34", title: "Guard for string search", starterCode: '// function findInString(str, search) mein dono strings do\n// Agar koi bhi string nahi: -1\n// Agar search empty: -1\n// Warna indexOf return karo\n', solution: 'function findInString(str, search) {\n  if (typeof str !== "string" || typeof search !== "string") return -1\n  if (search.length === 0) return -1\n  return str.indexOf(search)\n}', tests: [{ input: ["Hello World", "World"], expected: 6 }, { input: ["Hello World", ""], expected: -1 }, { input: [null, "test"], expected: -1 }, { input: ["Hello", "xyz"], expected: -1 }], hints: ["Dono strings ka type check karo", "Empty search ke liye -1 return karo"] },
  { id: "04-02-35", title: "Guard for object merge", starterCode: '// function mergeObjects(obj1, obj2) mein dono objects do\n// Agar koi bhi object nahi: {}\n// Dono ka spread merge karo\n', solution: 'function mergeObjects(obj1, obj2) {\n  if (typeof obj1 !== "object" || obj1 === null) return {}\n  if (typeof obj2 !== "object" || obj2 === null) return {}\n  return { ...obj1, ...obj2 }\n}', tests: [{ input: [{ a: 1 }, { b: 2 }], expected: { a: 1, b: 2 } }, { input: [{ a: 1 }, null], expected: {} }, { input: [null, { b: 2 }], expected: {} }], hints: ["typeof object aur null dono check karo", "Spread operator se merge hota hai"] },
  { id: "04-02-36", title: "Guard for email domain check", starterCode: '// function getDomain(email) mein email string do\n// Agar string nahi: null\n// Agar @ nahi hai: null\n// Warna @ ke baad ka part return karo\n', solution: 'function getDomain(email) {\n  if (typeof email !== "string") return null\n  if (!email.includes("@")) return null\n  return email.split("@")[1]\n}', tests: [{ input: ["test@gmail.com"], expected: "gmail.com" }, { input: ["invalid"], expected: null }, { input: [123], expected: null }, { input: ["test@"], expected: "" }], hints: ["@ se split karo", "Dusra part domain hai"] },
  { id: "04-02-37", title: "Guard for sorted array", starterCode: '// function isSorted(arr) mein array do\n// Agar array nahi: false\n// Agar empty ya single element: true\n// Ascending mein sorted hai ya nahi check karo\n', solution: 'function isSorted(arr) {\n  if (!Array.isArray(arr)) return false\n  if (arr.length <= 1) return true\n  for (let i = 1; i < arr.length; i++) {\n    if (arr[i] < arr[i - 1]) return false\n  }\n  return true\n}', tests: [{ input: [[1, 2, 3, 4, 5]], expected: true }, { input: [[5, 4, 3, 2, 1]], expected: false }, { input: [[]], expected: true }, { input: [[1]], expected: true }], hints: ["Loop se consecutive elements compare karo", "Agar koi bhi pair galat hai to false"] },
  { id: "04-02-38", title: "Guard for array element existence", starterCode: '// function includes(arr, value) mein array aur value do\n// Agar array nahi: false\n// Agar value nahi: false\n// Warna includes return karo\n', solution: 'function includes(arr, value) {\n  if (!Array.isArray(arr)) return false\n  if (value === undefined || value === null) return false\n  return arr.includes(value)\n}', tests: [{ input: [[1, 2, 3], 2], expected: true }, { input: [[1, 2, 3], 4], expected: false }, { input: [null, 1], expected: false }, { input: [[1, 2], null], expected: false }], hints: ["Array type check karo pehle", "Value existence bhi check karo"] },
  { id: "04-02-39", title: "Guard for string replacement", starterCode: '// function replaceAll(str, search, replacement) mein teen strings do\n// Agar koi bhi string nahi: ""\n// Agar search empty: original string\n// Warna replaceAll use karo\n', solution: 'function replaceAll(str, search, replacement) {\n  if (typeof str !== "string" || typeof search !== "string" || typeof replacement !== "string") return ""\n  if (search.length === 0) return str\n  return str.replaceAll(search, replacement)\n}', tests: [{ input: ["Hello World", "World", "JS"], expected: "Hello JS" }, { input: ["aaa", "a", "b"], expected: "bbb" }, { input: ["Hello", "", "X"], expected: "Hello" }, { input: [123, "2", "X"], expected: "" }], hints: ["Sab strings ka type check karo", "Empty search pe original return karo"] },
  { id: "04-02-40", title: "Guard for number formatting", starterCode: '// function formatPrice(num) mein number do\n// Agar number nahi: "₹0.00"\n// Agar negative: "₹0.00"\n// Warna "₹{num.toFixed(2)}"\n', solution: 'function formatPrice(num) {\n  if (typeof num !== "number" || Number.isNaN(num)) return "₹0.00"\n  if (num < 0) return "₹0.00"\n  return `₹${num.toFixed(2)}`\n}', tests: [{ input: [100], expected: "₹100.00" }, { input: [3.14159], expected: "₹3.14" }, { input: [-50], expected: "₹0.00" }, { input: ["abc"], expected: "₹0.00" }], hints: ["typeof aur NaN dono check karo", "toFixed(2) se do decimal places milte hain"] },
  { id: "04-02-41", title: "Guard for array chunking", starterCode: '// function chunk(arr, size) mein array aur chunk size do\n// Agar array nahi: []\n// Agar size <= 0: []\n// Warna chunks mein divide karo\n', solution: 'function chunk(arr, size) {\n  if (!Array.isArray(arr)) return []\n  if (size <= 0) return []\n  const chunks = []\n  for (let i = 0; i < arr.length; i += size) {\n    chunks.push(arr.slice(i, i + size))\n  }\n  return chunks\n}', tests: [{ input: [[1, 2, 3, 4, 5], 2], expected: [[1, 2], [3, 4], [5]] }, { input: [[1, 2, 3], 5], expected: [[1, 2, 3]] }, { input: [[], 2], expected: [] }, { input: [[1, 2], 0], expected: [] }], hints: ["Loop mein slice se chunks banao", "Step size se array ko divide karo"] },
  { id: "04-02-42", title: "Guard for string reversal", starterCode: '// function reverse(str) mein string do\n// Agar string nahi: ""\n// Agar empty string: ""\n// Warna reverse string return karo\n', solution: 'function reverse(str) {\n  if (typeof str !== "string") return ""\n  return str.split("").reverse().join("")\n}', tests: [{ input: ["hello"], expected: "olleh" }, { input: [""], expected: "" }, { input: [123], expected: "" }, { input: ["a"], expected: "a" }], hints: ["split('') se array banta hai", "reverse() se array reverse hota hai"] },
  { id: "04-02-43", title: "Guard for number comparison", starterCode: '// function compare(a, b) mein do values do\n// Agar dono numbers nahi: null\n// Agar a > b: 1, a < b: -1, a === b: 0\n', solution: 'function compare(a, b) {\n  if (typeof a !== "number" || typeof b !== "number") return null\n  if (a > b) return 1\n  if (a < b) return -1\n  return 0\n}', tests: [{ input: [5, 3], expected: 1 }, { input: [3, 5], expected: -1 }, { input: [5, 5], expected: 0 }, { input: ["a", 5], expected: null }], hints: ["Dono ka type number check karo", "Standard comparison result do"] },
  { id: "04-02-44", title: "Guard for array deduplication", starterCode: '// function unique(arr) mein array do\n// Agar array nahi: []\n// Agar empty: []\n// Warna unique values return karo\n', solution: 'function unique(arr) {\n  if (!Array.isArray(arr)) return []\n  if (arr.length === 0) return []\n  return [...new Set(arr)]\n}', tests: [{ input: [[1, 2, 2, 3, 3, 3]], expected: [1, 2, 3] }, { input: [["a", "b", "a"]], expected: ["a", "b"] }, { input: [[]], expected: [] }, { input: [null], expected: [] }], hints: ["Set sirf unique values rakhta hai", "Spread operator se array mein convert karo"] },
  { id: "04-02-45", title: "Guard for string trimming", starterCode: '// function clean(str) mein string do\n// Agar string nahi: ""\n// Trim karo\n// Empty hai to: ""\n// Warna cleaned string do\n', solution: 'function clean(str) {\n  if (typeof str !== "string") return ""\n  const trimmed = str.trim()\n  if (trimmed.length === 0) return ""\n  return trimmed\n}', tests: [{ input: ["  hello  "], expected: "hello" }, { input: ["   "], expected: "" }, { input: [123], expected: "" }, { input: ["hi"], expected: "hi" }], hints: ["Trim se leading/trailing spaces hati hain", "Empty check karo baad mein"] },
  { id: "04-02-46", title: "Guard for object keys", starterCode: '// function getKeys(obj) mein object do\n// Agar object nahi: []\n// Agar array hai: []\n// Warna Object.keys return karo\n', solution: 'function getKeys(obj) {\n  if (typeof obj !== "object" || obj === null || Array.isArray(obj)) return []\n  return Object.keys(obj)\n}', tests: [{ input: [{ a: 1, b: 2 }], expected: ["a", "b"] }, { input: [null], expected: [] }, { input: [[1, 2, 3]], expected: [] }, { input: [undefined], expected: [] }], hints: ["typeof object aur null dono check karo", "Array bhi object hota hai — usse alag karo"] },
  { id: "04-02-47", title: "Guard for number range validation", starterCode: '// function inRange(val, min, max) mein teen numbers do\n// Agar koi bhi non-number: false\n// Val range mein hai ya nahi\n', solution: 'function inRange(val, min, max) {\n  if (typeof val !== "number" || typeof min !== "number" || typeof max !== "number") return false\n  return val >= min && val <= max\n}', tests: [{ input: [5, 1, 10], expected: true }, { input: [15, 1, 10], expected: false }, { input: [0, 1, 10], expected: false }, { input: ["a", 1, 10], expected: false }], hints: ["Teeno parameters ka type check karo", "Range check karo: val >= min && val <= max"] },
  { id: "04-02-48", title: "Guard for array filtering", starterCode: '// function filterBy(arr, predicate) mein array aur function do\n// Agar array nahi: []\n// Agar function nahi: []\n// Warna filter karo\n', solution: 'function filterBy(arr, predicate) {\n  if (!Array.isArray(arr)) return []\n  if (typeof predicate !== "function") return []\n  return arr.filter(predicate)\n}', tests: [{ input: [[1, 2, 3, 4], x => x > 2], expected: [3, 4] }, { input: [["a", "b", "c"], x => x !== "b"], expected: ["a", "c"] }, { input: [null, x => x], expected: [] }], hints: ["Array type check karo", "Predicate function check karo"] },
  { id: "04-02-49", title: "Guard for string concatenation", starterCode: '// function joinWords(...words) mein words do\n// Agar koi word nahi: ""\n// Agar koi non-string hai: "Invalid word"\n// Warna space se join karo\n', solution: 'function joinWords(...words) {\n  if (words.length === 0) return ""\n  if (words.some(w => typeof w !== "string")) return "Invalid word"\n  return words.join(" ")\n}', tests: [{ input: ["Hello", "World"], expected: "Hello World" }, { input: [], expected: "" }, { input: ["Hello", 123, "World"], expected: "Invalid word" }], hints: ["Length check pehle karo", "Sab words ka type string check karo"] },
  { id: "04-02-50", title: "Guard for complex data processing", starterCode: '// function processData(data) mein object do\n// Agar data nahi: null\n// Agar data.users nahi: null\n// Agar data.users array nahi: null\n// Warna users ki names array return karo\n', solution: 'function processData(data) {\n  if (!data) return null\n  if (!data.users) return null\n  if (!Array.isArray(data.users)) return null\n  return data.users.map(u => u.name).filter(Boolean)\n}', tests: [{ input: [{ users: [{ name: "Hariom" }, { name: "Amit" }] }], expected: ["Hariom", "Amit"] }, { input: [{ users: null }], expected: null }, { input: [null], expected: null }, { input: [{ users: "not array" }], expected: null }], hints: ["Har level pe null/undefined check karo", "Array.isArray() se type verify karo"] },
])
